function out = sim_one_rep(d, T, B, seed, tr)
%SIM_ONE_REP  One replication of the estimator simulations: rank step, dynamic least squares
%   weights, VAR in (R, W, G) and the bootstrap schemes
%   oracle (pseudo-true weights known), fixed (estimated weights held fixed), refit (weights
%   re-estimated with the controls at their observed values), joint (controls regenerated by the
%   joint VAR in (dX1, S, R, W, G), weights re-estimated), jointrc (joint, recentred at the bootstrap
%   population value, Theorem thm:joint), plainvar (VAR without controls).
HM = 24; s = RandStream('mt19937ar', 'Seed', seed);
S = sim_simulate(d, T, s);
Y1 = S.Y1; Y0 = S.Y0; R = S.R; W = S.W; K = size(Y0, 2);
[m, D1, Hc] = sim_rank_step(Y0);
[a, b] = cvar.dols(Y1, Y0, [R, W], D1, [], 12, 1, d.constrained);
G = Y1 - a - Y0 * b;
Z = [R, W, G];
p = sim_choose_lag(Z, d.lagrule);
[A, U] = cvar.var_fit(Z, p);
resp = @(A_, U_, p_) pick3(cvar.irf(A_, U_, p_, 2, HM));
est = resp(A, U, p);
lb_rej = cvar.ljungbox_p(U(:, 3), 12) <= 0.05;
Zo = [R, W, Y1 - tr.a_star - Y0 * tr.b_star]; [Ao, Uo] = cvar.var_fit(Zo, p); est_o = resp(Ao, Uo, p);
Zv = [R, W, Y1]; [Av, Uv] = cvar.var_fit(Zv, p); est_v = resp(Av, Uv, p);
if m > 0, Dfull = [D1, Hc]; else, Dfull = eye(K); end
Xr = Y0 * Dfull; rh = size(D1, 2);
J = [diff(Xr(:, 1:rh), 1, 1), Xr(2:end, rh + 1:end), R(2:end), W(2:end), G(2:end)];
if isfield(d, 'joint_lags') && ~isempty(d.joint_lags), pj = min(d.joint_lags, p); else, pj = p; end
[Aj, Uj] = cvar.var_fit(J, pj);
Dinv = inv(Dfull);           % Xr = Y0 Dfull, so Y0 = Xr inv(Dfull)
sims = @(A_, U_, Z0, p_, n_) cvar.var_sim(A_, U_, Z0, p_, n_, randi(s, size(U_, 1), n_ - p_, 1));
draws = struct('oracle', zeros(B, HM + 1), 'fixed', zeros(B, HM + 1), 'refit', zeros(B, HM + 1), ...
    'joint', zeros(B, HM + 1), 'plainvar', zeros(B, HM + 1));
for i = 1:B
    Zs = sims(Ao, Uo, Zo(1:p, :), p, T); [A2, U2] = cvar.var_fit(Zs, p); draws.oracle(i, :) = resp(A2, U2, p);
    Zs = sims(A, U, Z(1:p, :), p, T); [A2, U2] = cvar.var_fit(Zs, p); draws.fixed(i, :) = resp(A2, U2, p);
    Zs = sims(A, U, Z(1:p, :), p, T);
    y1s = a + Y0 * b + Zs(:, 3);
    [a2, b2] = cvar.dols(y1s, Y0, Zs(:, 1:2), D1, [], 12, 1, d.constrained);
    [A2, U2] = cvar.var_fit([Zs(:, 1:2), y1s - a2 - Y0 * b2], p); draws.refit(i, :) = resp(A2, U2, p);
    Js = sims(Aj, Uj, J(1:pj, :), pj, T - 1);
    draws.joint(i, :) = rebuild(Js, Xr, rh, K, Dinv, R, W, G, a, b, D1, d, p, resp);
    Zs = sims(Av, Uv, Zv(1:p, :), p, T); [A2, U2] = cvar.var_fit(Zs, p); draws.plainvar(i, :) = resp(A2, U2, p);
end
if isfield(d, 'recentre_mult') && ~isempty(d.recentre_mult), mult = d.recentre_mult; else, mult = 50; end
JL = sims(Aj, Uj, J(1:pj, :), pj, mult * (T - 1));
pop = rebuild(JL, Xr, rh, K, Dinv, R, W, G, a, b, D1, d, p, resp);
draws.jointrc = draws.joint + (est - pop);
out = struct('rank_coint', m, 'p', p, 'pj', pj, 'lb_rej', lb_rej);
for k = {'oracle', 'fixed', 'refit', 'joint', 'jointrc', 'plainvar'}
    switch k{1}
        case 'oracle', pt = est_o;
        case 'plainvar', pt = est_v;
        otherwise, pt = est;
    end
    q = cvar.quantile7(draws.(k{1}), [0.05 0.95]);
    out.(k{1}) = struct('point', pt, 'lo', q(1, :), 'hi', q(2, :));
end
end

function r = pick3(R)
r = R(:, 3)';
end

function g = rebuild(Js, Xr, rh, K, Dinv, R, W, G, a, b, D1, d, p, resp)
% Controls, policies and treated outcome from a path of the joint VAR; weights re-estimated.
X1s = [Xr(1, 1:rh); Xr(1, 1:rh) + cumsum(Js(:, 1:rh), 1)];
Ss = [Xr(1, rh + 1:end); Js(:, rh + 1:K)];
Y0s = [X1s, Ss] * Dinv;
Rs = [R(1); Js(:, K + 1)]; Ws = [W(1); Js(:, K + 2)]; Gs = [G(1); Js(:, K + 3)];
y1s = a + Y0s * b + Gs;
[a2, b2] = cvar.dols(y1s, Y0s, [Rs, Ws], D1, [], 12, 1, d.constrained);
[A2, U2] = cvar.var_fit([Rs, Ws, y1s - a2 - Y0s * b2], p);
g = resp(A2, U2, p);
end
